import{z as e}from"zod";import{ACCEPTED_CONVERSION_EXAMPLES as o,FAMILY_ROUTES as r,buildMigrationPlan as s}from"../lib/jdsMigration.js";import{text as l,errorText as d}from"./util.js";function u(n){n.registerTool("jds_to_oneui_migration",{title:"JDS \u2192 OneUI: rebuild a legacy Figma frame as a OneUI design frame",description:'Start here when the user hands a Figma frame built with the legacy JDS / Jio Testlab library and wants it rebuilt with OneUI \u2014 "convert this JDS screen to OneUI", "migrate this Testlab frame", "redesign this v3 screen with OneUI components". Produces a NEW OneUI design frame in Figma; it does not generate code (for code from a Figma URL use `figma_to_code`).\n\nReturns the complete rebuild instruction set as ordered **official Figma MCP** calls \u2014 `mcp__figma__get_screenshot`, `get_metadata`, `use_figma`, `search_design_system` \u2014 with the Plugin-API code already written and ready to run. YOU execute them; this tool never touches Figma.\n\nWhat it resolves offline so you never guess: which skills to load and in what order, every JDS component mapped to its OneUI target plus a verified Figma component key, which of the 12 behaviour-grouped prop tables owns each component, the root variable-mode table (including the en-dash collection names that silently match nothing), and the traps that make a wrong swap look right.\n\nTwo-pass by design: call it once to get the inventory snippet, run that through `use_figma`, then call again passing `inventory` and `cloneId` to get the swap and audit snippets fully materialised \u2014 no hand-editing of JS.',inputSchema:{figmaUrl:e.string().url().describe("URL of the legacy JDS frame to rebuild, WITH a node-id \u2014 e.g. https://www.figma.com/design/<fileKey>/<name>?node-id=275-22028. In Figma: right-click the frame \u2192 Copy link to selection. A bare file URL is rejected."),conversion:e.string().optional().describe(`Which conversion this is. Free-form, legacy side first; all of ${o.map(t=>`"${t}"`).join(", ")} resolve to the canonical \`v3-to-oneui\`. Rejected if it reads as OneUI \u2192 JDS (the reverse direction). Defaults to \`v3-to-oneui\`.`),targetFileUrl:e.string().url().optional().describe("Figma file to place the rebuild in. Defaults to the source file, in which case the rebuild goes beside the source frame and the source is left untouched. A different file must already have the OneUI libraries enabled."),platform:e.enum(["mobile","web"]).optional().default("mobile").describe("Selects the root variable-mode set. `mobile` pins `09 Platform: S \u2013 360` and `11 Density: default` so the px\u2192token divisor is 4; `web` omits both so you set the breakpoint you are designing at."),components:e.array(e.string()).optional().describe(`Legacy component names already known to be on the frame (e.g. ["Button", "Input"]). Pre-resolves them into the resolution table and narrows the prop-table list from all ${r.length} families to only those needed. Names with no owning family are reported as unmapped rather than guessed.`),inventory:e.array(e.object({name:e.string().describe("Layer name of the instance."),path:e.array(e.number().int()).describe("Child-index path from the frame root."),mainName:e.string().nullable().optional().describe("Resolved main-component name.")})).optional().describe("The `instances` array returned by the step-3 inventory snippet. Supplying it (with `cloneId`) materialises the swap snippet: each instance resolved against the component map, nested instances excluded, hidden state preserved."),cloneId:e.string().optional().describe("The `cloneId` returned by the step-5 clone snippet. Required alongside `inventory` to materialise the swap and audit snippets, which must target the clone rather than the source."),frameName:e.string().optional().describe("Name for the rebuild frame. Defaults to `<source name> \u2014 OneUI`."),offsetY:e.number().int().min(0).max(5e3).optional().default(80).describe("Vertical gap between the source frame and the rebuild. Default 80."),maxNodes:e.number().int().min(1).max(2e4).optional().default(6e3).describe("Traversal budget baked into the inventory snippet. If it reports `truncated: true`, raise this and re-run before cloning \u2014 a rebuild reasoned from a partial inventory will miss nodes."),includeSkillBody:e.boolean().optional().default(!1).describe("Inline the full `legacy-to-oneui` skill body (~70KB) instead of having you call `get_skill` for it. Leave false unless chaining calls is not possible.")}},async({conversion:t,...a})=>{const i=s({...a,conversion:t??"v3-to-oneui"});return i.ok?l(i.markdown):d(i.markdown)})}export{u as registerJdsMigrationTools};
